/* JavaScript Node ACM模式 控制台输入获取 */
const rl = require("readline").createInterface({
  input: process.stdin,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 3) {
    const n = lines[0] - 0;
    const positions = lines[1].split(" ").map(Number);
    const m = lines[2] - 0;

    console.log(getResult(n, positions, m));

    lines.length = 0;
  }
});

function getResult(n, positions, m) {
  positions.sort((a, b) => a - b);

  let min = 1;
  let max = positions[n - 1] - positions[0];
  let ans = 0;

  while (min <= max) {
    const mid = (min + max) >> 1;
    if (check(positions, m, mid)) {
      ans = mid;
      min = mid + 1;
    } else {
      max = mid - 1;
    }
  }

  return ans;
}

function check(positions, m, minDis) {
  let count = 1;
  let curPos = positions[0];

  for (let i = 1; i < positions.length; i++) {
    if (positions[i] - curPos >= minDis) {
      count++;
      curPos = positions[i];
    }
  }

  return count >= m;
}

