#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100000

int getResult(int n, int* positions, int m);
int cmp(const void* a, const void* b);
int check(int* positions, int n, int m, int minDis);

int main()
{
	// 适合种树的坐标数量
	int n;
	scanf("%d", &n);

	// 适合种树的坐标位置
	int positions[MAX_SIZE];
	for(int i=0; i<n; i++) {
		scanf("%d", &positions[i]);
	}

	// 树苗的数量
	int m;
	scanf("%d", &m);

	printf("%d\n", getResult(n, positions, m));

	return 0;
}

int getResult(int n, int* positions, int m)
{
	qsort(positions, n, sizeof(int), cmp);

	int min = 1;
	int max = positions[n-1] - positions[0];

	int ans = 0;

	while(min <= max) {
		int mid = (min + max) >> 1;

		if(check(positions, n, m, mid)) {
			ans = mid;
			min = mid + 1;
		} else {
			max = mid - 1;
		}
	}

	return ans;
}

int cmp(const void* a, const void* b)
{
	return *((int*) a) - *((int*) b);
}

int check(int* positions, int n, int m, int minDis)
{
	int count = 1;

	int curPos = positions[0];
	for(int i=1; i<n; i++) {
		if(positions[i] - curPos >= minDis) {
			count++;
			curPos = positions[i];
		}
	}

	return count >= m;
}
